565	  let maxDanger = 0;
566	  for (let i = 0; i < 400 && S().mode === 'play'; i++) { G.upd(1); if (S().dangerT > maxDanger) maxDanger = S().dangerT; }
567	  assert(21, S().mode === 'over', '堆过警戒线 2 秒判负');
568	  assert(22, frames.some(f => f.kind === 'gameOver'), 'gameOver 上报帧');
569	
