1	// WebAudio synthesis: SFX (drop/merge/combo/lose/ui/firework) + two-state
2	// music loop (calm / danger) with soft crossfade. All synthesized, no assets.
3	// BGM volume kept ≈ 1/4 of SFX per skill vfx-ui-audio guidance.
4	
5	export function makeAudio() {
6	  let ctx = null, master = null, sfxG = null, musG = null;
7	  let muted = false, state = 'calm', musTimer = 0, step16 = 0;
8	  const states = {
9	    calm:   { bpm: 76, chords: [[220, 277.2, 329.6], [174.6, 220, 261.6], [196, 246.9, 293.7], [164.8, 207.6, 246.9]], arp: [0, 1, 2, 1], density: .4, wave: 'sine' },
10	    danger: { bpm: 108, chords: [[196, 233, 293.7], [185, 220, 277.2], [174.6, 207.6, 261.6], [164.8, 196, 246.9]], arp: [0, 2, 1, 2, 0, 1], density: .85, wave: 'triangle' },
11	  };
12	
13	  function ensure() {
14	    if (ctx) return true;
15	    try {
16	      ctx = new (window.AudioContext || window.webkitAudioContext)();
17	    } catch (e) { return false; }
18	    master = ctx.createGain(); master.gain.value = muted ? 0 : 1; master.connect(ctx.destination);
19	    sfxG = ctx.createGain(); sfxG.gain.value = .8; sfxG.connect(master);
20	    musG = ctx.createGain(); musG.gain.value = .22; musG.connect(master);
21	    return true;
22	  }
23	  const now = () => ctx.currentTime;
24	
25	  function tone({ f = 440, f2, type = 'sine', t = .2, v = .3, at = 0, decay = .12, dest }) {
26	    const o = ctx.createOscillator(), g = ctx.createGain();
27	    o.type = type; o.frequency.setValueAtTime(f, now() + at);
28	    if (f2) o.frequency.exponentialRampToValueAtTime(Math.max(20, f2), now() + at + t);
29	    g.gain.setValueAtTime(0, now() + at);
30	    g.gain.linearRampToValueAtTime(v, now() + at + .012);
31	    g.gain.exponentialRampToValueAtTime(.001, now() + at + t + decay);
32	    o.connect(g); g.connect(dest || sfxG);
33	    o.start(now() + at); o.stop(now() + at + t + decay + .05);
34	  }
35	  function noise({ t = .18, v = .25, at = 0, f = 1200, q = 1 }) {
36	    const len = Math.ceil(ctx.sampleRate * (t + .05));
37	    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
38	    const d = buf.getChannelData(0);
39	    for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, 2);
40	    const src = ctx.createBufferSource(); src.buffer = buf;
41	    const flt = ctx.createBiquadFilter(); flt.type = 'bandpass'; flt.frequency.value = f; flt.Q.value = q;
42	    const g = ctx.createGain(); g.gain.value = v;
43	    src.connect(flt); flt.connect(g); g.connect(sfxG);
44	    src.start(now() + at);
45	  }
46	
47	  // --- SFX library ---
48	  const sfx = {
49	    drop(tier) {
50	      if (!ctx) return;
51	      const f = 320 - tier * 22;
52	      tone({ f, f2: f * .55, type: 'sine', t: .1, v: .3 });
53	      noise({ t: .08, v: .12, f: 500, q: .8 });
54	    },
55	    merge(tier, combo) {
56	      if (!ctx) return;
57	      const base = 300 + tier * 26 + Math.min(combo, 6) * 40;
58	      tone({ f: base, f2: base * 1.5, type: 'triangle', t: .12, v: .3 });
59	      tone({ f: base * 2, type: 'sine', t: .08, v: .16, at: .04 });
60	      noise({ t: .1, v: .1, f: 1800, q: 1.2 });
61	    },
62	    comboUp(n) {
63	      if (!ctx) return;
64	      tone({ f: 520 + n * 60, type: 'square', t: .09, v: .12 });
65	      tone({ f: 780 + n * 90, type: 'square', t: .09, v: .1, at: .07 });
66	    },
67	    bigMerge() {
68	      if (!ctx) return;
69	      [523, 659, 784, 1046].forEach((f, i) => tone({ f, type: 'triangle', t: .16, v: .22, at: i * .07 }));
70	    },
71	    firework() {
