      const cx = w.x + w.w / 2, cy = w.y + w.h / 2;
      c.beginPath(); c.moveTo(cx - 8, cy - 4); c.lineTo(cx - 3, cy + 2); c.lineTo(cx + 2, cy - 4); c.stroke();
      c.beginPath(); c.moveTo(cx + 3, cy - 4); c.lineTo(cx + 8, cy + 2); c.lineTo(cx + 13, cy - 4); c.stroke();
    }
  }
