import { LEVELS } from '/mnt/tos/workspace/packages/games/whisper-heist/js/levels.js';
import { circleRect } from '/mnt/tos/workspace/packages/games/whisper-heist/js/stealth.js';
const STEP=6, R=9;
function insideAny(x,y,walls){ return walls.some(w=>circleRect(x,y,R,w)); }
function bfs(lv, tallOnly){
  const walls = tallOnly ? lv.walls.filter(w=>w.type!=='low') : lv.walls;
  const W=960,H=540;
  const passable=(x,y)=> x>R && x<W-R && y>R && y<H-R && !insideAny(x,y,walls);
  const key=(x,y)=>`${Math.round(x/STEP)},${Math.round(y/STEP)}`;
  const sx=Math.round(lv.start.x/STEP)*STEP, sy=Math.round(lv.start.y/STEP)*STEP;
  if(!passable(sx,sy)) return {ok:false, reason:'start blocked', reach:()=>false};
  const q=[[sx,sy]], seen=new Set([key(sx,sy)]);
  while(q.length){const [x,y]=q.shift();for(const [dx,dy] of [[STEP,0],[-STEP,0],[0,STEP],[0,-STEP]]){const nx=x+dx,ny=y+dy,k=key(nx,ny);if(seen.has(k)||!passable(nx,ny))continue;seen.add(k);q.push([nx,ny]);}}
  return {ok:true,reach:(pt)=>seen.has(key(Math.round(pt.x/STEP)*STEP,Math.round(pt.y/STEP)*STEP))};
}
for(let i=0;i<LEVELS.length;i++){
  const lv=LEVELS[i]; const tall=bfs(lv,true); const all=bfs(lv,false);
  let issues=[];
  for(const [n,pt] of [['start',lv.start],...lv.relics.map((r,j)=>['relic'+j,r])]) {
    if(!tall.reach(pt)) issues.push(n+' unreachable even crouching');
    else if(!all.reach(pt)) issues.push(n+' needs crouch (ok)');
  }
  const ec={x:lv.exit.x+lv.exit.w/2,y:lv.exit.y+lv.exit.h/2};
  if(!tall.reach(ec)) issues.push('exit unreachable'); else if(!all.reach(ec)) issues.push('exit needs crouch (ok)');
  for(const [j,g] of lv.guards.entries()) if(insideAny(g.x,g.y,lv.walls)) issues.push('guard'+j+' in wall');
  for(const [j,r] of lv.relics.entries()) if(insideAny(r.x,r.y,lv.walls)) issues.push('relic'+j+' in wall');
  if(insideAny(lv.start.x,lv.start.y,lv.walls)) issues.push('start in wall');
  if(insideAny(ec.x,ec.y,lv.walls)) issues.push('exit in wall');
  console.log(String(i+1).padStart(2), lv.name.padEnd(8), 'issues:', issues.length?issues.join(', '):'none');
}
